import {validateGameRules} from './game-rules.js';
import {regionProfile} from './region-map.js';
import {movementAt} from './world-model.js';
const int=(n,a,b)=>Number.isInteger(n)&&n>=a&&n<=b;
const STOCK='3d0c79f1627022e18765766f6cb5ea067f6b5bf7dca115552189ad65a5c3a8ac';
export function travelProfile(hash){if(regionProfile(hash).engine==='emerald')throw Error('Spawn, Fly and cursor editing needs an Emerald travel adapter. Town Map painting and names are available.');return hash===STOCK?{spawn:0x549f8,heal:0x3eebf8,grids:[0x3f2490,0x3f2724,0x3f29b8,0x3f2c4c]}:{spawn:0x57cf4,heal:0x413a70,grids:[0x417308,0x41759c,0x417830,0x417ac4]};}
export function readTravel(reader,hash){const p=travelProfile(hash);for(const [offset,opcode]of [[8,0x2000],[12,0x2000],[14,0x2100],[16,0x2300]])if((reader.u16(p.spawn+offset)&0xff00)!==opcode)throw Error('The new-game spawn instructions failed verification.');if(reader.u16(p.spawn)!==0xb500||reader.u16(p.spawn+6)!==0x4252)throw Error('The new-game warp helper failed verification.');
 const spawn={mapKey:reader.u8(p.spawn+12)+'.'+reader.u8(p.spawn+14),x:reader.u8(p.spawn+16),y:reader.u8(p.spawn+8)},fly=Array.from({length:20},(_,id)=>{const at=p.heal+id*8,mapKey=reader.u8(at)+'.'+reader.u8(at+1),map=reader.byKey(mapKey);if(!map)throw Error('A Fly landing map is missing.');return{id,mapKey,x:reader.u16(at+2),y:reader.u16(at+4),name:map.label||mapKey};}),grids=p.grids.map(at=>Array.from(reader.bytes.slice(at,at+660)));if(grids.some(g=>g.length!==660||g.some(n=>n<88||n>197)))throw Error('The cursor-selection grid failed verification.');return{profile:p,spawn,fly,grids};}
export function validateTravelEdits(edits){if(edits===undefined)return;if(!edits||Array.isArray(edits)||Object.keys(edits).length>16)throw Error('Invalid travel edits.');for(const [hash,e]of Object.entries(edits)){if(!/^[a-f0-9]{64}$/.test(hash)||!e||!e.fly||!e.grids)throw Error('Invalid travel source.');validateGameRules(e.rules);if(e.spawn){const s=e.spawn;if(!(typeof s.mapKey==='string'&&/^\d+\.\d+$/.test(s.mapKey)||typeof s.mapId==='string')||!int(s.x,0,255)||!int(s.y,0,255))throw Error('Choose a new-game map and coordinates from 0 to 255.');}for(const [id,s]of Object.entries(e.fly))if(!/^\d+$/.test(id)||!int(+id,0,19)||!s||!int(s.x,0,32767)||!int(s.y,0,32767))throw Error('Invalid Fly landing.');for(const [id,g]of Object.entries(e.grids))if(!/^[0-3]$/.test(id)||!Array.isArray(g)||g.length!==660||g.some(n=>!int(n,88,197)))throw Error('Invalid cursor-selection grid.');}}
function point(reader,mapKey,s,project,byId){const target=s.mapId?byId.get(s.mapId):null,native=target?.native||reader.byKey(mapKey);if(!native||native.bank>127||native.index>127)throw Error('The travel destination is not an exported map.');const authored=target?.map||project.maps.find(m=>m.rom?.key===native.key&&!m.rom?.isCopy),width=authored?.width??native.layout.width,height=authored?.height??native.layout.height;if(s.x>=width||s.y>=height)throw Error('The travel tile is outside its map.');const rule=authored?movementAt(authored,s.x,s.y):{collision:(reader.u16(native.layout.blocks+(s.y*width+s.x)*2)>>10)&3};if(rule?.collision||rule?.mode?.startsWith('ledge_')||authored?.fieldObjects?.some(o=>o.x===s.x&&o.y===s.y))throw Error('Choose a clear landing tile.');return native;}
export function installTravel(project,reader,hash,output,byId=new Map()){const e=project.travelEdits?.[hash];if(!e)return[];validateTravelEdits({[hash]:e});const n=readTravel(reader,hash),reports=[];if(e.spawn){const s=e.spawn,map=point(reader,s.mapKey,s,project,byId),at=n.profile.spawn;output.write(at+8,Uint8Array.of(s.y));output.write(at+12,Uint8Array.of(map.bank));output.write(at+14,Uint8Array.of(map.index));output.write(at+16,Uint8Array.of(s.x));reports.push('New game starts at '+map.key+' · '+s.x+','+s.y);}
 for(const [id,s]of Object.entries(e.fly)){const old=n.fly[id];point(reader,old.mapKey,s,project,byId);output.int(n.profile.heal+Number(id)*8+2,s.x,2);output.int(n.profile.heal+Number(id)*8+4,s.y,2);reports.push('Fly landing: '+old.name+' · '+s.x+','+s.y);}for(const [id,g]of Object.entries(e.grids)){output.write(n.profile.grids[id],Uint8Array.from(g));reports.push('Town Map cursor grid '+(Number(id)+1)+' · both layers');}return reports;}
